// The dangi (Korean) calendar: ICU's month table for related ISO years -6000..2200 (calendar_dangi_data.inc, generated by
// tools/temporal/gen-calendars.mjs), mean lunations outside it.
#include "builtins/temporal/calendar_lunisolar.h"

namespace snowman::temporal {

namespace {
#include "builtins/temporal/calendar_dangi_data.inc"

const LunisolarTableCalendar kDangi({kDangiFirstYear, kDangiFirstNewYear, kDangiYears});
static_assert(sizeof(kDangiYears) / sizeof(kDangiYears[0]) == size_t(kDangiLastYear - kDangiFirstYear + 1));
}  // namespace

const CalendarSystem* DangiCalendarSystem() { return &kDangi; }

}  // namespace snowman::temporal
